[풀이]
d와 s를 vector<int>로 받는다. 최솟값·최댓값은 시작값을 d[0]으로 두고 min()/max()로 갱신한다. 시작값을 0으로 두면 모두 양수일 때 최솟값이, 모두 음수일 때 최댓값이 틀린다. 판매자 수는 bool seen[100001] 배열에 '나온 적 있나'를 표시하며 처음 나올 때만 센다. 배열 크기는 번호 100,000이 들어가도록 100,001 이상이어야 한다. 시간 복잡도 O(N).

[모범 코드]
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

bool seen[100001];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    vector<int> d(n), s(n);
    for (int i = 0; i < n; ++i) cin >> d[i];
    for (int i = 0; i < n; ++i) cin >> s[i];
    int lo = d[0], hi = d[0];
    for (int x : d) {
        lo = min(lo, x);
        hi = max(hi, x);
    }
    int kinds = 0;
    for (int x : s) {
        if (!seen[x]) {
            seen[x] = true;
            ++kinds;
        }
    }
    cout << lo << ' ' << hi << '\n' << kinds << '\n';
    return 0;
}

