(1) 3중 for(i < j < k)로 모든 조합을 보고 DigitSum(a[i] + a[j] + a[k])의 최댓값을 구한다. 합은 최대 300,000이라 int로 충분. O(N³) ≈ 16만 번.
(2) 7골드 주화 개수 big을 G / 7부터 0까지 바꿔 가며, 남은 금액 G − 7·big이 4로 나누어떨어지는지 본다. 나누어떨어지는 첫 big에서 big + 나머지/4가 최소다(7골드 하나를 더 쓰면 같은 금액에서 주화가 줄어들기 때문). 모든 big을 다 보고 최솟값을 고르는 풀이도 정답. 큰 주화부터 한 번만 나누는 탐욕(G / 7개 쓰고 끝)은 G = 8, 15처럼 틀린다. O(G).

[모범 코드]
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int DigitSum(int x) {
    int s = 0;
    while (x > 0) {
        s += x % 10;
        x /= 10;
    }
    return s;
}

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (auto& x : a) cin >> x;
    int g;
    cin >> g;
    int best = 0;
    for (int i = 0; i < n; ++i)
        for (int j = i + 1; j < n; ++j)
            for (int k = j + 1; k < n; ++k)
                best = max(best, DigitSum(a[i] + a[j] + a[k]));
    cout << best << '\n';
    int ans = -1;
    for (int big = g / 7; big >= 0; --big) {
        int rest = g - 7 * big;
        if (rest % 4 == 0) {
            ans = big + rest / 4;
            break;
        }
    }
    cout << ans << '\n';
    return 0;
}

