    }
    set<string> hall;
    for (int i = 0; i < m; ++i) {
        string name, act;
        cin >> name >> act;
        if (act == "in") hall.insert(name);
        else hall.erase(name);
    }
    for (int i = 0; i < q; ++i) {
        string s;
        cin >> s;
        if (s[0] >= '0' && s[0] <= '9') cout << byNum[stoi(s)] << '\n';
        else if (toNum.count(s)) cout << toNum[s] << '\n';
        else cout << "NONE" << '\n';
