form_a.answer_key:
[풀이]
① deque<int>의 push_front / push_back / pop_front / pop_back / front / back / size로 명령을 그대로 옮긴다. 비었는지 먼저 확인. 명령이 50만 개라 빠른 입출력과 '\n'이 필요하다.
② stack<char>: 여는 괄호는 push, 닫는 괄호는 스택이 비었거나 top()이 같은 종류의 여는 괄호가 아니면 BROKEN, 맞으면 pop. 끝에 스택이 비어 있어야 OK.
③ queue<pair<int,int>>(번호, 남은 손상)에 1 … R을 넣고, front를 꺼내 min(C, 남은 손상)만큼 빼서 0이면 완성 순서에 기록, 아니면 다시 push(맨 뒤로). 반복 횟수는 최대 Σ⌈d_i / C⌉ ≤ 100만.
시간 복잡도 O(N + Σ문자열 길이 + Σd_i / C).

[모범 코드]
#include <iostream>
#include <string>
#include <deque>
#include <stack>
#include <queue>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    deque<int> dq;
    while (n--) {
        string cmd;
        cin >> cmd;
        if (cmd == "top") { int x; cin >> x; dq.push_front(x); }
        else if (cmd == "bottom") { int x; cin >> x; dq.push_back(x); }
        else if (cmd == "draw") {
            if (dq.empty()) cout << -1 << '\n';
            else { cout << dq.front() << '\n'; dq.pop_front(); }
        }
        else if (cmd == "burn") {
            if (dq.empty()) cout << -1 << '\n';
            else { cout << dq.back() << '\n'; dq.pop_back(); }
        }
        else if (cmd == "count") cout << dq.size() << '\n';
        else if (cmd == "peek") cout << (dq.empty() ? -1 : dq.front()) << '\n';
        else if (cmd == "last") cout << (dq.empty() ? -1 : dq.back()) << '\n';
    }
    int b;
    cin >> b;
    while (b--) {
        string s;
        cin >> s;
        stack<char> st;
        bool ok = true;
        for (char ch : s) {
            if (ch == '(' || ch == '[') st.push(ch);
            else {
                char want = (ch == ')') ? '(' : '[';
                if (st.empty() || st.top() != want) { ok = false; break; }
                st.pop();
            }
        }
        if (!st.empty()) ok = false;
        cout << (ok ? "OK" : "BROKEN") << '\n';
    }
    int r, hit;
    cin >> r >> hit;
    queue<pair<int, int>> q;
    for (int i = 1; i <= r; ++i) {
        int d;
        cin >> d;
        q.push({i, d});
    }
    bool first = true;
    while (!q.empty()) {
        pair<int, int> cur = q.front();
        q.pop();
        cur.second -= min(hit, cur.second);
        if (cur.second == 0) {
            cout << (first ? "" : " ") << cur.first;
            first = false;
        }
        else q.push(cur);
    }
    cout << '\n';
    return 0;
}

