[풀이]
스킬 번호를 먼저 sort해야 사전순 출력이 된다.
① 순열: 재귀 DFS + bool used[]. 고르고(used = true, push) → 재귀 → 되돌리기(pop, used = false).
② 조합: 시작 인덱스 start를 매개변수로 넘겨 i = start부터 고르고 Comb(i + 1).
③ 중복 수열: used 없이 매번 0부터 고른다.
(2) 연산자 개수 배열 op[4]를 상태로 들고 다니는 백트래킹 Calc(idx, val): op[o] > 0이면 op[o]-- → Calc(idx + 1, 새 값) → op[o]++. idx == K에서 최댓값·최솟값 갱신. ÷는 C++ / 그대로.
시간: 순열 ≤ 720, 중복 ≤ 6^6 = 46656줄, 연산자 경우 ≤ 10!/(3!3!2!2!) 수준.

[모범 코드]
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int n, m, k;
vector<int> skill, pick, a;
bool used[6];
int op[4];
int best = -1000000000, worst = 1000000000;

void Print() {
    for (int i = 0; i < m; ++i) cout << pick[i] << (i + 1 < m ? ' ' : '\n');
}

void Perm() {
    if ((int)pick.size() == m) { Print(); return; }
    for (int i = 0; i < n; ++i) {
        if (used[i]) continue;
        used[i] = true;
        pick.push_back(skill[i]);
        Perm();
        pick.pop_back();
        used[i] = false;
    }
}

void Comb(int start) {
    if ((int)pick.size() == m) { Print(); return; }
    for (int i = start; i < n; ++i) {
        pick.push_back(skill[i]);
        Comb(i + 1);
        pick.pop_back();
    }
}

void Rep() {
    if ((int)pick.size() == m) { Print(); return; }
    for (int i = 0; i < n; ++i) {
        pick.push_back(skill[i]);
        Rep();
        pick.pop_back();
    }
}

void Calc(int idx, int val) {
    if (idx == k) {
        best = max(best, val);
        worst = min(worst, val);
        return;
    }
    for (int o = 0; o < 4; ++o) {
        if (op[o] == 0) continue;
        op[o]--;
        int b = a[idx], nv;
        if (o == 0) nv = val + b;
        else if (o == 1) nv = val - b;
        else if (o == 2) nv = val * b;
        else nv = val / b;
        Calc(idx + 1, nv);
        op[o]++;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m;
    skill.resize(n);
    for (auto& x : skill) cin >> x;
    sort(skill.begin(), skill.end());
    cin >> k;
    a.resize(k);
    for (auto& x : a) cin >> x;
    for (int i = 0; i < 4; ++i) cin >> op[i];
    Perm(); cout << "--" << '\n';
    Comb(0); cout << "--" << '\n';
    Rep(); cout << "--" << '\n';
    Calc(1, a[0]);
    cout << best << '\n' << worst << '\n';
    return 0;
}

