form_a.answer_key:
[풀이]
인접 리스트 vector<int> adj[1001]에 양방향으로 넣고 각 리스트를 오름차순 sort한다.
① 재귀 Dfs(u): visited 표시 → 순서 기록 → 인접 v 중 미방문이면 Dfs(v). DFS는 한 갈래를 끝까지 파고들어 1 2 4 3, BFS는 가까운 방부터 1 2 3 4로 순서가 다르다.
② queue: 시작점을 넣고 방문 표시, 꺼낼 때 기록, 미방문 인접 방을 표시하고 push(넣을 때 표시해야 중복 방문이 없다).
③ DFS 방문 수 − 1.
④ 1 … N을 돌며 미방문 방에서 탐색을 새로 시작할 때마다 무리 수 + 1(네트워크형).
⑤ 재귀 Target(i, sum)에서 세 갈래(+c_i, −c_i, 그대로)로 뻗고 i == L에서 sum == T이면 센다(타겟 넘버형 변형). 3^12 = 531,441번.
시간 복잡도 O(N + E log E + 3^L).

[모범 코드]
#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

vector<int> adj[1001];
bool visD[1001], visB[1001], visC[1001];
vector<int> order;
int L, T, ways = 0;
vector<int> c;

void Dfs(int u) {
    visD[u] = true;
    order.push_back(u);
    for (int v : adj[u])
        if (!visD[v]) Dfs(v);
}

void Mark(int u) {
    visC[u] = true;
    for (int v : adj[u])
        if (!visC[v]) Mark(v);
}

void Target(int i, int sum) {
    if (i == L) {
        if (sum == T) ++ways;
        return;
    }
    Target(i + 1, sum + c[i]);
    Target(i + 1, sum - c[i]);
    Target(i + 1, sum);
}

int main() {
    int n, e, s;
    cin >> n >> e >> s;
    for (int i = 0; i < e; ++i) {
        int u, v;
        cin >> u >> v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }
    for (int i = 1; i <= n; ++i) sort(adj[i].begin(), adj[i].end());

    Dfs(s);
    for (int i = 0; i < (int)order.size(); ++i)
        cout << order[i] << (i + 1 < (int)order.size() ? ' ' : '\n');

    queue<int> q;
    q.push(s);
    visB[s] = true;
    bool first = true;
    while (!q.empty()) {
        int u = q.front();
        q.pop();
        cout << (first ? "" : " ") << u;
        first = false;
        for (int v : adj[u]) {
            if (!visB[v]) {
                visB[v] = true;
                q.push(v);
            }
        }
    }
    cout << '\n';

    cout << order.size() - 1 << '\n';

    int comp = 0;
    for (int i = 1; i <= n; ++i) {
        if (!visC[i]) {
            ++comp;
            Mark(i);
        }
    }
    cout << comp << '\n';

    cin >> L >> T;
    c.resize(L);
    for (auto& x : c) cin >> x;
    Target(0, 0);
    cout << ways << '\n';
    return 0;
}

[놓치기 쉬운 경우]
- 인접 리스트를 정렬하지 않음(입력 순서대로 방문)
- 한 방향으로만 간선 추가
- BFS에서 꺼낼 때 방문 표시 → 같은 방이 큐에 여러 번 들어가 순서 중복
- DFS·BFS가 같은 visited 배열을 써서 두 번째 탐색이 비어 버림
- ③에 S를 포함, ④에서 고립된 방을 빼먹음
- ⑤에서 '쓰지 않기' 갈래 누락

